return ['domain'=>NULL,'plural-forms'=>'nplurals=1; plural=0;','language'=>'uz_UZ','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:51:14+00:00','po-revision-date'=>'2026-11-05T19:51:14+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Saytingizda o‘rnatilgan plaginlar va mavzular uchun yetishmayotgan Translations ni to‘ldiradi.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Bu yuklash ekrani eskirgan: shundan keyin boshqa yuklash tayyorlangan. Hech narsa yuborilmadi. Joriy yuklashni Translations ro‘yxatidan ko‘rib chiqing.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Bepul xizmat rejasi har bir saytga plaginlar va mavzular uchun cheklangan miqdordagi slotlarni beradi; ishlatilayotgan slotlar Babilim yoqilgandan so‘ng Settings bo‘limida ko‘rsatiladi.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Tarjimani so‘rash bu plagin yoki mavzuni ushbu sayt uchun bepul xizmat rejasining slotlaridan biriga joylashtiradi (chegara: mavzular uchun %1$d, plaginlar uchun %2$d), agar u allaqachon slotda bo‘lmasa. Slot band bo‘lib qoladi va muvaffaqiyatsiz tarjima uni bo‘shatmaydi.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Tarjimani so‘rash bu plagin yoki mavzuni ushbu sayt uchun bepul xizmat rejasining slotlaridan biriga joylashtiradi, agar u allaqachon slotda bo‘lmasa. Slot band bo‘lib qoladi va muvaffaqiyatsiz tarjima uni bo‘shatmaydi.','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'Agar bu plagin yoki mavzu ushbu sayt uchun bepul xizmat rejasining slotlaridan birida hali bo‘lmasa, tarjimani so‘rash uni slotga joylashtiradi (chegara: mavzular uchun %1$d, plaginlar uchun %2$d). Slot band bo‘lib qoladi va muvaffaqiyatsiz tarjima uni bo‘shatmaydi. Davom etasizmi?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'Agar bu plagin yoki mavzu ushbu sayt uchun bepul xizmat rejasining slotlaridan birida hali bo‘lmasa, tarjimani so‘rash uni slotga joylashtiradi. Slot band bo‘lib qoladi va muvaffaqiyatsiz tarjima uni bo‘shatmaydi. Davom etasizmi?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Ushbu tarmoqdagi %1$d ta sayt plagin o\'chirilganda o\'z Babilim identifikatorini o\'chirishga sozlangan. Bunday saytlarga biriktirilgan pullik litsenziyani keyin avtomatik tiklab bo\'lmaydi; %2$s manzilida Babilim yordami bilan bog\'lanishingiz kerak bo\'ladi. Identifikatorlarni saqlab qolish uchun Bekor qilish tugmasini bosing, tegishli har bir saytning Babilim sozlamalarida "O\'chirishda Babilimning barcha ma\'lumotlarini o\'chirish" belgisini olib tashlang va plaginni yana faolsizlantiring. Baribir faolsizlantirilsinmi?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s bajariladigan ish yo\'q.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Tilni tanlang.','%d failed'=>'%d ta muvaffaqiyatsiz','%d not yet tried'=>'%d ta hali urinilmagan','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d ta hisobot kutmoqda. “Doimo ulashish” va “Ulashmaslik” ularning barchasiga tatbiq etiladi.','%d skipped'=>'%d ta o\'tkazib yuborildi','%d succeeded'=>'%d ta muvaffaqiyatli','%d to install'=>'%d ta o\'rnatishga tayyor','(a public key generated for this site)'=>'(ushbu sayt uchun yaratilgan ochiq kalit)','(detected)'=>'(aniqlangan)','(generic codes and coordinates only)'=>'(faqat umumiy kodlar va koordinatalar)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Tozalash %1$s da to\'xtatildi: %2$s. Hech narsa o\'chirilmadi.','A file in the component could not be read, so it was not packaged.'=>'Komponentdagi bitta faylni o‘qib bo‘lmadi, shuning uchun u paketga kiritilmadi.','A host that serves only one PHP request at a time cannot complete this step.'=>'Bir vaqtning o\'zida faqat bitta PHP so\'rovini bajaradigan hosting bu bosqichni yakunlay olmaydi.','A part of the upload kept failing, so the upload was cancelled.'=>'Yuklashning bir qismi qayta-qayta muvaffaqiyatsiz bo‘ldi, shuning uchun yuklash bekor qilindi.','A translation cannot be requested for that locale on this site right now.'=>'Hozir bu saytda ushbu til uchun tarjima so\'rab bo\'lmaydi.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Tarjimalar indeksiga yozish %1$s da (%2$s) boshqa so\'rov bilan to\'qnashdi va qo\'llanmadi; eng so\'nggi versiya saqlab qolindi.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Tarjimalar indeksiga %1$s da (%2$s) yozishni yakunlab bo\'lmadi va u qo\'llanmadi (%3$s).','Account'=>'Hisob','Add another language'=>'Yana til qo\'shish','Advanced'=>'Qo\'shimcha','All'=>'Barchasi','All free-plan slots for this site are used'=>'Ushbu sayt uchun bepul reja slotlarining barchasi band','All languages'=>'Barcha tillar','Already in WordPress core'=>'WordPress yadrosida allaqachon mavjud','Already installed.'=>'Allaqachon o\'rnatilgan.','Always share'=>'Doimo ulashish','Another installation is running; try again in a moment.'=>'Boshqa o\'rnatish jarayoni ishlamoqda; birozdan so\'ng qayta urinib ko\'ring.','Automatic installs'=>'Avtomatik o\'rnatishlar','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Avtomatik o\'rnatish endi o\'chirilgan; xohlasangiz, sozlamalarda uni qayta yoqing.','Available'=>'Mavjud','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Mavjud tarjimalarni bir marta bosish bilan o‘rnatish mumkin, yetishmayotganlarini esa so‘rash mumkin. Avtomatik o‘rnatishlar yoqilgan bo‘lsa, xizmat siz boshqarayotgan tillar uchun mavjud deb ko‘rsatgan tarjimalar kuniga ikki marta sinxronlash vaqtida o‘rnatiladi.','Available · %s'=>'Mavjud · %s','Babilim Settings'=>'Babilim sozlamalari','Babilim adds translations for every language checked here.'=>'Babilim bu yerda belgilangan har bir til uchun tarjimalar qo\'shadi.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim veb-sayt tashqarisidagi vaqtinchalik papkani tasdiqlay olmadi, shuning uchun komponent paketlanmadi va hech narsa yuklanmadi. wp-config.php faylida BABILIM_TEMP_DIR ni veb ildiz papkasidan tashqaridagi yozish mumkin bo‘lgan papka sifatida belgilang (masalan, saytingizning ommaviy katalogi ichida emas, uning yonidagi papka) yoki hosting provayderingizdan so‘rang.','Babilim could not finish checking this site.'=>'Babilim bu saytni tekshirishni yakunlay olmadi.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim yoqishni yakunlay olmadi (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim bu saytni tekshirishni yakunlay olmadi (xizmat saytga qayta ulana olmadi). Ro\'yxatdan o\'tkazish to\'xtatildi.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim bu saytni tasdiqlay olmadi, shuning uchun tasdiqlash muvaffaqiyatli bo‘lmaguncha hech narsa yuklab olinmaydi yoki o‘rnatilmaydi.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim bu saytni tasdiqlay olmadi, shuning uchun hech narsa yuklab olinmaydi yoki o\'rnatilmaydi.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim bu saytdagi tilingiz uchun tarjimasi yo\'q plaginlar va mavzularni topadi hamda ularning har biriga tarjima o\'rnatadi.','Babilim has not been enabled for this site yet.'=>'Babilim bu sayt uchun hali yoqilmagan.','Babilim has not installed any translation for this language.'=>'Babilim bu til uchun hech qanday tarjima o‘rnatmagan.','Babilim hit an error. Share an error report?'=>'Babilim xatolikka duch keldi. Xatolik hisobotini ulashasizmi?','Babilim installed %d translation automatically since your last visit.'=>'Oxirgi tashrifingizdan beri Babilim %d ta tarjimani avtomatik o\'rnatdi.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim o\'chirilgan. Boshqa hech narsa yuborilmaydi; allaqachon o\'rnatilgan tarjimalar ishlashda davom etadi.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim yoqilgan: bu sayt tasdiqlangan va %d ta komponent topildi.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim bu saytni yoqmoqda va tekshirmoqda… (oxirgi urinish: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim bu saytni yoqmoqda va tekshirmoqda… Bu sahifani qayta yuklang yoki rejalashtirilgan tekshiruv tugashini kuting.','Babilim is not enabled.'=>'Babilim yoqilmagan.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim plagin o\'chirilganda ushbu saytning identifikatorini o\'chirishga sozlangan. Ushbu saytga biriktirilgan pullik litsenziyani keyin avtomatik tiklab bo\'lmaydi; %s manzilida Babilim yordami bilan bog\'lanishingiz kerak bo\'ladi. Identifikatorni saqlab qolish uchun Bekor qilish tugmasini bosing, Babilim sozlamalarida "O\'chirishda Babilimning barcha ma\'lumotlarini o\'chirish" belgisini olib tashlang va plaginni yana faolsizlantiring. Baribir faolsizlantirilsinmi?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim bu qadam uchun ajratilgan vaqtdan oshib ketdi va keyingi tekshiruvda davom etadi.','Babilim settings'=>'Babilim sozlamalari','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim sinxronlash jarayoni xizmat tomonidan vaqtincha kechiktirildi (so\'rovlar chastotasi cheklangan); %s dan keyin qayta urinib ko\'riladi.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Bu yuklash kutilayotganda Babilim yangilandi. Eski paket bekor qilindi; iltimos, yuklashni qayta tasdiqlang.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim %1$s (versiya %2$s) uchun ushbu fayllarni yuklaydi: har bir .php va .js fayli, har bir block.json fayli hamda asosiy papkadagi readme.txt, readme.md, style.css va theme.json. Ular tarjima qilinishi kerak bo‘lgan matnni topish hamda plagin yoki mavzuni aniqlash uchun ishlatiladi.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest mavjud emas: %s','Back'=>'Orqaga','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Bu domen uchun avval litsenziya sotib olganmisiz? To\'lov vaqtida olgan tiklash kodingizni kiriting.','Broken placeholder'=>'Buzilgan o\'rin belgisi','Build'=>'Build','Built'=>'Yaratilgan','Bulk actions apply only to the selected language of each selected component.'=>'Ommaviy amallar tanlangan har bir komponentning faqat tanlangan tiliga qo\'llaniladi.','Bulk actions apply to every matching language of each selected component.'=>'Ommaviy amallar tanlangan har bir komponentning mos keladigan barcha tillariga qo\'llaniladi.','Bulk download:'=>'Ommaviy yuklab olish:','Bulk request:'=>'Ommaviy so\'rov:','Bulk update:'=>'Ommaviy yangilash:','Bundled with the plugin'=>'Plagin bilan birga keladi','Bundled with the theme'=>'Mavzu bilan birga keladi','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Yoqish tugmasini bosish orqali yuqorida sanab o\'tilgan ma\'lumotlarni Babilimga yuborishga rozilik bildirasiz.','By continuing you confirm that you have the right to upload this component.'=>'Davom etish orqali ushbu komponentni yuklash huquqiga ega ekanligingizni tasdiqlaysiz.','Cancel'=>'Bekor qilish','Category'=>'Toifa','Check again'=>'Qayta tekshirish','Check again now'=>'Hozir qayta tekshirish','Checkout is not available for this site right now.'=>'Hozirda bu sayt uchun to\'lov mavjud emas.','Choose'=>'Tanlash','Choose a category…'=>'Toifani tanlang…','Choose a language'=>'Tilni tanlang','Choose a language…'=>'Tilni tanlang…','Clear filters'=>'Filtrlarni tozalash','Close'=>'Yopish','Component'=>'Komponent','Confirm'=>'Tasdiqlash','Conflicting keys'=>'Ziddiyatli kalitlar','Continue'=>'Davom etish','Continue next batch (%d left)'=>'Keyingi to‘plamni davom ettirish (%d ta qoldi)','Continuing…'=>'Davom etilmoqda…','Could not back up %s before replacing it.'=>'%s almashtirilishidan oldin uning zaxira nusxasini yaratib bo‘lmadi.','Could not create the package archive.'=>'Paket arxivini yaratib bo‘lmadi.','Could not determine active components; the existing merged index was left unchanged.'=>'Faol komponentlarni aniqlab bo\'lmadi; mavjud birlashtirilgan indeks o\'zgartirilmadi.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'O\'rnatilgan plagin/mavzularni aniqlab bo\'lmadi; tozalash o\'tkazib yuborildi, hech narsa o\'chirilmadi.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Xizmatdan WordPress.org lokallarining to\'liq ro\'yxatini yuklab bo\'lmadi, shuning uchun hozir boshqa til qo\'shib bo\'lmaydi.','Could not move %s into place.'=>'%s faylini joyiga ko‘chirib bo‘lmadi.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' uchun birlashtirilgan indeksni joyiga ko\'chirib bo\'lmadi; oldingi xizmat ko\'rsatilgan indeks (agar bo\'lsa) yarim yangilangan holda qoldirilmay, o\'chirildi. Keyingi muvaffaqiyatli qayta qurishgacha bu til uchun standart domen qo\'shimchasi taqdim etilmaydi.','Could not open zip: %s'=>'zip faylni ochib bo\'lmadi: %s','Could not prepare %s for rollback.'=>'%s ni orqaga qaytarishga tayyorlab bo\'lmadi.','Could not read %s back after moving it into place.'=>'%s joyiga ko\'chirilgandan so\'ng uni qayta o\'qib bo\'lmadi.','Could not read: %s'=>'O‘qib bo‘lmadi: %s','Could not restore the purchase: %s'=>'Xaridni tiklab bo\'lmadi: %s','Could not show a new restore code: %s'=>'Yangi tiklash kodini ko\'rsatib bo\'lmadi: %s','Could not stage %s'=>'%s faylini tayyorlab bo‘lmadi','Could not stage default/%s'=>'default/%s faylini tayyorlab bo‘lmadi','Could not start checkout: %s'=>'To\'lovni boshlab bo\'lmadi: %s','Could not verify entry count for %s'=>'%s uchun yozuvlar sonini tekshirib bo‘lmadi','Could not write the downloaded package to disk.'=>'Yuklab olingan paketni diskka yozib bo\'lmadi.','Could not write the staged merged index.'=>'Bosqichma-bosqich birlashtirilgan indeksni yozib bo\'lmadi.','Current translation'=>'Joriy tarjima','Custom overrides'=>'Maxsus o\'zgartirishlar','Danger zone'=>'Xavfli hudud','Default supplement entry count mismatch.'=>'Standart qo‘shimchadagi yozuvlar soni mos kelmadi.','Delete all Babilim data on uninstall'=>'O\'chirishda Babilimning barcha ma\'lumotlarini o\'chirish','Disable Babilim'=>'Babilim\'ni o\'chirish','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim\'ni o\'chirasizmi? O\'rnatilgan tarjimalar saqlanadi, lekin boshqa tekshiruvlar va yuklab olishlar bajarilmaydi.','Don\'t share'=>'Ulashmaslik','Download'=>'Yuklab olish','Downloaded and installed.'=>'Yuklab olindi va o\'rnatildi.','Downloading…'=>'Yuklab olinmoqda…','Downloads: %1$d/%2$d (%3$s)'=>'Yuklab olishlar: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Har bir komponentning har bir tilning umumiy standart domen qo\'shimchasiga qo\'shgan o\'z hissasi.','Enable Babilim'=>'Babilim\'ni yoqish','Enabling…'=>'Yoqilmoqda…','English (United States)'=>'Ingliz tili (Amerika Qo‘shma Shtatlari)','Entries'=>'Yozuvlar','Entry count mismatch for %s'=>'%s uchun yozuvlar soni mos kelmadi','Error reports'=>'Xatolik hisobotlari','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'O\'rnatilgan har bir plagin/mavzu: uning slugi, versiyasi, matn domen(lar)i, wp.org ro\'yxatida bor-yo\'qligi, o\'zi bilan kelgan tillar va qaysi tillar uchun Babilim tarjimasini allaqachon o\'rnatganingiz.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Ushbu saytda ishlatilayotgan barcha lokallar (sayt lokali, o\'rnatilgan til paketlari, foydalanuvchi lokallari va qo\'lda qo\'shganlaringiz). Barcha lokallarga bir xil munosabatda bo\'linadi.','Excluded'=>'Chiqarib tashlangan','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Boshqa nom yoki kengaytmali fayllar, shuningdek uploads, cache, logs, backup, data, vendor, node_modules va languages papkalari, yashirin fayllar hamda nomi keng tarqalgan maxfiy ma’lumotlarga mos keladigan fayllar (wp-config*, .env*, *.sql, *.log, *.pem, *.key) kiritilmaydi. Kod fayllarida baribir boshqalar bilan ulashishni xohlamaydigan matn yoki ma’lumotlar bo‘lishi mumkin; ishonchingiz komil bo‘lmasa, ularni tekshiring. Fayllar xizmatga kelib tushganda, xizmat xuddi shu turdagi fayllarni yana olib tashlaydi.','Free'=>'Bepul','Free-plan slots'=>'Bepul reja slotlari','General'=>'Umumiy','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Agar bu yoqilgan bo\'lsa, o\'chirishda ushbu saytning identifikatori ham o\'chiriladi. Ushbu saytga biriktirilgan pullik litsenziyani keyin avtomatik tiklab bo\'lmaydi; uni qaytarish uchun %s manzilida Babilim yordami bilan bog\'lanishingiz kerak bo\'ladi.','Included'=>'Kiritilgan','Included in index'=>'Indeksga kiritilgan','Install available translations automatically'=>'Mavjud tarjimalarni avtomatik o\'rnatish','Installed'=>'O\'rnatilgan','Installed translations are kept, but no further checks or downloads will run.'=>'O\'rnatilgan tarjimalar saqlanadi, lekin boshqa tekshiruvlar va yuklab olishlar bajarilmaydi.','Installed · %s'=>'O\'rnatilgan · %s','Installed · built for %1$s, this site has %2$s'=>'O\'rnatilgan · %1$s uchun yaratilgan, bu saytda %2$s mavjud','Installed · built for %s'=>'O\'rnatilgan · %s uchun yaratilgan','Installed · built for %s, all free-plan slots for this site are used'=>'O‘rnatilgan · %s uchun yaratilgan, ushbu sayt uchun bepul reja slotlarining barchasi band','Installed · built for %s, new version failed'=>'O\'rnatilgan · %s uchun tuzilgan, yangi versiya muvaffaqiyatsiz','Installed · built for %s, new version not covered by the free service plan'=>'O‘rnatilgan · %s uchun yaratilgan, yangi versiya bepul xizmat rejasiga kirmaydi','Installed · built for %s, new version scheduled'=>'O\'rnatilgan · %s uchun yaratilgan, yangi versiya rejalashtirilgan','Installed · built for %s, translating the new version…'=>'O\'rnatilgan · %s uchun yaratilgan, yangi versiya tarjima qilinmoqda…','Installed · built for a different version'=>'O\'rnatilgan · boshqa versiya uchun yaratilgan','Installed · built for a different version, all free-plan slots for this site are used'=>'O‘rnatilgan · boshqa versiya uchun yaratilgan, ushbu sayt uchun bepul reja slotlarining barchasi band','Installed · built for a different version, new version failed'=>'O\'rnatilgan · boshqa versiya uchun tuzilgan, yangi versiya muvaffaqiyatsiz','Installed · built for a different version, new version not covered by the free service plan'=>'O‘rnatilgan · boshqa versiya uchun yaratilgan, yangi versiya bepul xizmat rejasiga kirmaydi','Installed · built for a different version, new version scheduled'=>'O\'rnatilgan · boshqa versiya uchun yaratilgan, yangi versiya rejalashtirilgan','Installed · built for a different version, translating the new version…'=>'O\'rnatilgan · boshqa versiya uchun yaratilgan, yangi versiya tarjima qilinmoqda…','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'U xizmatning xosting provayderi tomonidan saqlanadi va tarjimani yaratish uchun sun’iy intellekt modellari tomonidan qayta ishlanadi.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Hammasini tozalashda yoki ushbu plaginni o\'chirishda mening tarjima o\'zgartirishlarimni saqlash.','Language'=>'Til','Language:'=>'Til:','Languages'=>'Tillar','Languages found on this site: %s.'=>'Bu saytda topilgan tillar: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'So\'nggi tozalash %1$s da: %2$d yangi belgilandi, %3$d fayl o\'chirildi, %4$d yozuv olib tashlandi.','Maintenance'=>'Texnik xizmat','Maintenance status is not available right now.'=>'Xizmat ko\'rsatish holati hozir mavjud emas.','Manifest unavailable: %s'=>'Manifest mavjud emas: %s','Negation reversed'=>'Inkor ma\'nosi teskari bo\'lgan','No'=>'Yo\'q','No build is available to download for this locale.'=>'Bu til uchun yuklab olish mumkin bo\'lgan yig\'ilma yo\'q.','No cleanup has run yet.'=>'Hali tozalash bajarilmagan.','No components match these filters. %s'=>'Bu filtrlarga mos komponent yo\'q. %s','No components synced yet.'=>'Hali hech qanday komponent sinxronlanmagan.','No installed translation matches.'=>'Mos keladigan o‘rnatilgan tarjima topilmadi.','No language is managed yet.'=>'Hozircha birorta til boshqarilmaydi.','No pending challenge for this nonce.'=>'Bu nonce uchun kutilayotgan so\'rov yo\'q.','No pending challenge to verify.'=>'Tasdiqlash uchun kutilayotgan chaqiriq yo‘q.','No plugins or themes found.'=>'Hech qanday plagin yoki mavzu topilmadi.','No previous build to roll back to.'=>'Orqaga qaytariladigan oldingi build yo\'q.','No record for %s'=>'%s uchun yozuv yo‘q','No site id is on file to rotate a token for.'=>'Tokenni almashtirish uchun fayllarda saqlangan sayt identifikatori yo‘q.','No — component inactive'=>'Yo\'q — komponent nofaol','No — component removed'=>'Yo\'q — komponent olib tashlangan','No — installed version differs from the active one'=>'Yo\'q — o\'rnatilgan versiya faol versiyadan farq qiladi','Not a valid server_build_id: %s'=>'Yaroqli server_build_id emas: %s','Not covered by the free service plan'=>'Bepul xizmat rejasiga kirmaydi','Not installed'=>'O‘rnatilmagan','Not registered yet'=>'Hali ro\'yxatdan o\'tmagan','Not supported'=>'Qo\'llab-quvvatlanmaydi','Not verified'=>'Tasdiqlanmagan','Note (optional)'=>'Izoh (ixtiyoriy)','Nothing to choose.'=>'Tanlash uchun hech narsa yo‘q.','Nothing to confirm.'=>'Tasdiqlash uchun hech narsa yo‘q.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Odatda o\'chirilgan: plaginni o\'chirish bu saytning identifikatorini saqlab qoladi, shuning uchun qayta o\'rnatishda undan foydalanish mumkin.','One or more served files no longer match the manifest.'=>'Bir yoki bir nechta berilgan fayl endi manifest bilan mos kelmaydi.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Ushbu sayt uchun bir martalik xarid: %1$s %2$s. Barcha kelgusi tarjima yangilanishlarini o\'z ichiga oladi. To\'lovni Paddle yangi yorliqda amalga oshiradi.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Buni faqat tarmoq administratori bajara oladi, chunki bu ushbu tarmoqdagi barcha saytlar uchun umumiy bo\'lgan tarjima fayllarini o\'zgartiradi.','Only plugins and themes can be packaged.'=>'Faqat plaginlar va mavzularni paketlash mumkin.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Faqat WordPress.org’da mavjud bo‘lmagan plagin yoki mavzu uchun yuklashni tasdiqlaganingizda: har bir .php va .js fayli, har bir block.json fayli hamda shu komponentning asosiy papkasidagi readme.txt, readme.md, style.css va theme.json fayllari — keng tarqalgan maxfiy ma’lumotlarga mos keladigan fayllar chiqarib tashlangach, zip ko‘rinishida.','Open Babilim settings'=>'Babilim sozlamalarini ochish','Original language'=>'Asl til','Original string'=>'Asl satr','Paid'=>'Pullik','Partner'=>'Hamkor','Please check that your site can be reached from the internet, then try again.'=>'Iltimos, saytingizga internetdan kirish mumkinligini tekshiring va qayta urinib ko\'ring.','Please choose a category for this report.'=>'Iltimos, bu xabar uchun turkumni tanlang.','Plugin'=>'Plagin','Plugin · %s'=>'Plagin · %s','Plugins'=>'Plaginlar','Preview'=>'Oldindan ko\'rish','Purchase restored. This site is now licensed.'=>'Xarid tiklandi. Endi bu sayt litsenziyalangan.','Re-parsed entry count did not match the built index.'=>'Qayta tahlil qilingan yozuvlar soni tuzilgan indeksga mos kelmadi.','Re-verify'=>'Qayta tasdiqlash','Rebuild index now'=>'Indeksni hozir qayta qurish','Refusing to write outside the Babilim language-file directory.'=>'Babilim til fayllari katalogidan tashqariga yozishni rad etdim.','Registration response was missing required fields.'=>'Ro‘yxatdan o‘tkazish javobida zarur maydonlar yetishmadi.','Registration restarted.'=>'Ro\'yxatdan o\'tish qayta boshlandi.','Remove'=>'Olib tashlash','Remove everything Babilim installed'=>'Babilim o\'rnatgan hamma narsani olib tashlash','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim o\'rnatgan hamma narsa olib tashlansinmi? Bu Babilim ushbu saytdagi barcha plagin va mavzular uchun o\'rnatgan barcha til fayllarini o\'chiradi.','Remove the %2$s translation of %1$s from this site?'=>'%1$s komponentining %2$s tilidagi tarjimasi bu saytdan olib tashlansinmi?','Removed %d installed component.'=>'%d ta o\'rnatilgan komponent olib tashlandi.','Removed after a failed integrity check'=>'Yaxlitlikni tekshirish muvaffaqiyatsiz tugagani sababli olib tashlandi','Removed.'=>'Olib tashlandi.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Babilim bu saytdagi barcha plagin va mavzular uchun o\'rnatgan barcha til fayllarini olib tashlaydi.','Report a problem'=>'Muammo haqida xabar berish','Report translation'=>'Tarjima haqida xabar berish','Request newer translation'=>'Yangiroq tarjimani so\'rash','Request translation'=>'Tarjimani so\'rash','Requestable'=>'So\'rash mumkin','Requesting…'=>'So\'ralmoqda…','Restart registration'=>'Ro\'yxatdan o\'tkazishni qayta boshlash','Restore code'=>'Tiklash kodi','Restore purchase'=>'Xaridni tiklash','Retry request'=>'So\'rovni qayta yuborish','Roll back'=>'Orqaga qaytarish','Roll back and report'=>'Orqaga qaytarish va xabar berish','Roll back and send report'=>'Orqaga qaytarish va hisobot yuborish','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s komponentining %2$s tilidagi tarjimasi oldingi buildga qaytarilsinmi?','Rolled back and reported.'=>'Qaytarildi va xabar berildi.','Rolled back to the previous build.'=>'Oldingi buildga qaytarildi.','Rolled back, but the report could not be sent: %s'=>'Qaytarildi, lekin xabarni yuborib bo\'lmadi: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Orqaga qaytarish \'%1$s\' (%2$s) faylini ustidan yozadi, u hozir boshqa o‘rnatilgan komponent (%3$s) uchun xizmat qilmoqda; hech narsa o‘zgartirilmadi.','Rotate-token response was missing site_token.'=>'Tokenni almashtirish javobida site_token yetishmadi.','Save changes'=>'O\'zgarishlarni saqlash','Scheduled, waiting to be processed'=>'Rejalashtirilgan, qayta ishlashni kutmoqda','Search'=>'Qidirish','Search components'=>'Komponentlarni qidirish','Search the installed translations'=>'O‘rnatilgan tarjimalarni qidirish','Select all'=>'Hammasini tanlash','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Kamroq komponent tanlang: har bir ishga ko\'pi bilan %1$d ta amal (siz %2$d ta tanladingiz).','Send report'=>'Hisobot yuborish','Service plan'=>'Xizmat rejasi','Settings'=>'Sozlamalar','Share error reports'=>'Xatolik hisobotlarini ulashish','Share this report'=>'Ushbu hisobotni ulashish','Show a new restore code'=>'Yangi tiklash kodini ko\'rsatish','Show the "Report translation" entry in the admin toolbar'=>'Administrator asboblar panelida “Tarjima haqida xabar berish” bandini ko‘rsatish','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Ushbu komponent matnining bir qismi muallifi tomonidan bevosita kodga yozilgan va uni til paketi orqali tarjima qilib bo\'lmaydi.','Status'=>'Holati','Status unknown'=>'Holat noma\'lum','String context'=>'Satr konteksti','Suggested translation'=>'Taklif etilgan tarjima','Supplementary translation index'=>'Qo\'shimcha tarjimalar indeksi','Supplementary translation index rebuilt.'=>'Qo\'shimcha tarjimalar indeksi qayta qurildi.','Supplementary translation maintenance'=>'Qo\'shimcha tarjimalarga xizmat ko\'rsatish','Supplementary translations'=>'Qo\'shimcha tarjimalar','Sweep aborted without orphaning anything: %s.'=>'Tozalash hech narsani egasiz qoldirmasdan bekor qilindi: %s.','Sweep complete: %d file deleted.'=>'Skanerlash yakunlandi: %d ta fayl o\'chirildi.','Sweep now'=>'Hozir skanerlash','Sync complete.'=>'Sinxronlash yakunlandi.','Thank you. Your report was sent.'=>'Rahmat. Xabaringiz yuborildi.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Bu komponent ushbu saytda o\'rnatilmagan, shuning uchun u uchun tarjima so\'rab bo\'lmaydi.','That does not look like a restore code.'=>'Bu tiklash kodiga o\'xshamaydi.','That is not a valid WordPress locale code. Nothing was saved.'=>'Bu yaroqli WordPress mahalliy til kodi emas. Hech narsa saqlanmadi.','That is not a valid build identifier.'=>'Bu yaroqli build identifikatori emas.','The change could not be recorded in the translation index; please try again.'=>'O\'zgarish tarjimalar indeksiga yozilmadi; qayta urinib ko\'ring.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Tozalash bajarildi, lekin ba\'zi o\'zgarishlarni tarjimalar indeksida qayd etib bo\'lmadi; keyingi tozalashda ularni qayd etishga yana uriniladi.','The component has no files that can be uploaded.'=>'Komponentda yuklash mumkin bo‘lgan fayllar yo‘q.','The component is not inside the plugins or themes directory.'=>'Komponent plaginlar yoki mavzular katalogi ichida emas.','The component\'s main file was not found.'=>'Komponentning asosiy fayli topilmadi.','The download response was missing a usable location.'=>'Yuklab olish javobida foydalanish mumkin bo‘lgan manzil yo‘q edi.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Bu band Babilim ushbu saytda o‘rnatgan tarjimalarni qidirish va ulardan biri haqida xabar berish uchun panelni ochadi.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'"%1$s" maydoni juda uzun: u %2$d belgidan iborat, chegara esa %3$d. Hech narsa yuborilmadi; iltimos, uni qisqartirib, qayta urinib ko\'ring.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Berilgan \'%1$s\' domeni paket manifestidagi \'%2$s\' slugiga ham, \'%3$s\' text_domain qiymatiga ham mos kelmaydi.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' uchun birlashtirilgan indeks qayta qurildi, lekin tarjimalar indeksi uni qayd eta olmadi; keyingi qayta qurish yana urinadi.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Asl matn va undan yaratilgan tarjimalar xuddi shu versiyani o‘rnatadigan boshqa saytlarga taqdim etiladi.','The package declares no main translation file.'=>'Paketda asosiy tarjima fayli ko‘rsatilmagan.','The package has no %s for its own text domain.'=>'Paketda o\'zining matn domeni uchun %s yo\'q.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Paket manifestidagi \'%1$s\' turi so\'ralgan \'%2$s\' turiga mos kelmaydi.','The package produced no servable main translation file.'=>'Paket xizmat ko‘rsatish mumkin bo‘lgan asosiy tarjima faylini yaratmadi.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Paketning matn domeni \'%1$s\' ushbu saytdagi komponent nusxasining (\'%2$s\') matn domeniga mos kelmaydi, shuning uchun o\'rnatilmadi.','The packaged component could not be read.'=>'Paketlangan komponentni o‘qib bo‘lmadi.','The registration challenge is not in the expected form.'=>'Ro\'yxatdan o\'tish uchun tekshiruv topshirig\'i kutilgan shaklda emas.','The report could not be sent.'=>'Hisobotni yuborib bo‘lmadi.','The search could not be completed.'=>'Qidiruvni yakunlab bo‘lmadi.','The service asked this site to wait before syncing again.'=>'Xizmat bu saytdan qayta sinxronlashdan oldin kutishni so\'radi.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Xizmat saytingizga ulana olmadi. Ehtimol, xavfsizlik devori, xavfsizlik plagini yoki hosting qoidasi so\'rovni to\'sib qo\'ymoqda; iltimos, /wp-json/babilim/v1/challenge manziliga so\'rovlarga ruxsat bering.','The service\'s upload offer was incomplete.'=>'Xizmatning yuklash taklifi to‘liq emas edi.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'\'%1$s\' matn domeni (%2$s) boshqa o\'rnatilgan komponent (%3$s) uchun allaqachon taqdim etilgan; hech narsa o\'rnatilmadi.','The upload is kept until you ask Babilim to delete it.'=>'Yuklangan fayllar siz Babilim’dan ularni o‘chirishni so‘ramaguningizcha saqlanadi.','Theme'=>'Mavzu','Theme · %s'=>'Mavzu · %s','Themes'=>'Mavzular','There is no upload in progress.'=>'Davom etayotgan yuklash yo‘q.','There is no upload waiting for confirmation.'=>'Tasdiqlashni kutayotgan yuklash yo‘q.','These are the languages this site uses. You can change them in %s.'=>'Bu sayt foydalanadigan tillar. Ularni %s orqali o‘zgartirishingiz mumkin.','These fields will be sent:'=>'Quyidagi maydonlar yuboriladi:','This build is not one this site currently knows about for this component/locale.'=>'Bu build ushbu sayt uchun ushbu komponent/mahalliy til bo\'yicha hozir ma\'lum emas.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Bu komponent versiya raqamini ko\'rsatmagan, shuning uchun u uchun tarjima so\'rab bo\'lmaydi.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Bu komponent xizmat qabul qiladigan hajmdan katta, shuning uchun uni yuklab bo‘lmaydi.','This component was already uploaded. Babilim is checking it now.'=>'Bu komponent allaqachon yuklangan. Babilim uni hozir tekshirmoqda.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Bu komponentning versiya raqami %d belgidan uzun, Babilim buni qayta ishlay olmaydi, shuning uchun u uchun tarjima so\'rab bo\'lmaydi.','This issues a new restore code and the previous one stops working. Continue?'=>'Bu yangi tiklash kodini beradi va avvalgisi ishlamay qoladi. Davom etasizmi?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Bu tarmoqda saytlar juda ko\'p, ularni birma-bir tekshirib bo\'lmaydi va ba\'zilari plagin o\'chirilganda Babilim identifikatorini o\'chirishga sozlangan bo\'lishi mumkin. Bunday saytga biriktirilgan pullik litsenziyani keyin avtomatik tiklab bo\'lmaydi; %s manzilida Babilim yordami bilan bog\'lanishingiz kerak bo\'ladi. Identifikatorlarni saqlab qolish uchun Bekor qilish tugmasini bosing, har bir saytning Babilim sozlamalarida "O\'chirishda Babilimning barcha ma\'lumotlarini o\'chirish" belgisini olib tashlang va plaginni yana faolsizlantiring. Baribir faolsizlantirilsinmi?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Ushbu plaginning o\'z versiyasi, shunda u juda eski bo\'lib, xizmat bilan aloqa qila olmasa, xizmat uni yangilashni aytishi mumkin.','This report does not name a valid plugin or theme and locale.'=>'Bu xabarda to\'g\'ri plagin yoki mavzu va til ko\'rsatilmagan.','This report does not name an installed string.'=>'Bu hisobotda o‘rnatilgan satr ko‘rsatilmagan.','This report is missing a valid build to report against.'=>'Bu hisobotda hisobot berish uchun yaroqli build yo\'q.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Ushbu hisobot GitHub’da ochiq e’lon qilinadi va uchinchi tomonlar tomonidan saqlanishi mumkin.','This restore code was not recognised for this site.'=>'Bu tiklash kodi ushbu sayt uchun tanilmadi.','This site already has an active registration that can no longer be recovered automatically.'=>'Bu saytda faol ro\'yxatdan o\'tish mavjud, uni endi avtomatik tiklab bo\'lmaydi.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Bu saytda %2$d ta tilda %1$d ta komponent bor, buning uchun %3$d ta tekshiruv to‘plami kerak; Babilim har bir ishga tushirishda ko‘pi bilan %4$d tasini bajara oladi. Sozlamalarda boshqariladigan tillarni kamaytiring yoki ishlatilmayotgan plaginlar va mavzularni faolsizlantiring, so‘ng Hozir qayta tekshirish tugmasini bosing.','This site has no purchase to show a code for.'=>'Bu saytda kod ko\'rsatiladigan xarid yo\'q.','This site is already licensed. Reload the page.'=>'Bu saytga allaqachon litsenziya berilgan. Sahifani qayta yuklang.','This site is not registered with Babilim yet.'=>'Bu sayt hali Babilim\'da ro\'yxatdan o\'tmagan.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Bu sayt xizmat bir sinxronlashda qabul qiladigan hajmdan oshib ketgan, shuning uchun ba\'zi elementlar qoldirildi: %1$d ta komponent va %2$d ta til.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Bu sayt ko\'p saytli tarmoqning bir qismi bo\'lib, yangi tarjimalarni avtomatik o\'rnatmaydi. Allaqachon o\'rnatilgan tarjimalar baribir yangilanadi.','This site is verified.'=>'Bu sayt tasdiqlangan.','This site must be verified first.'=>'Avval ushbu sayt tasdiqlanishi kerak.','This site\'s URL, so the service can verify you own it.'=>'Ushbu saytning URL manzili, shunda xizmat sizga tegishli ekanini tekshira oladi.','This site\'s address is too long for Babilim to register.'=>'Bu saytning manzili Babilim ro‘yxatdan o‘tkazishi uchun juda uzun.','This site\'s configured locale.'=>'Ushbu saytning sozlangan lokali.','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Ushbu saytning o\'rnatish ochiq kaliti, so\'rovlar haqiqatan ham shu saytdan kelganini isbotlash uchun ishlatiladi. Faqat ochiq qismi yuboriladi.','This site\'s locale code is not one Babilim can register.'=>'Bu saytning mahalliy til kodi Babilim ro\'yxatdan o\'tkaza oladigan kod emas.','This string can\'t be reported from this site.'=>'Bu satr haqida ushbu saytdan xabar berib bo‘lmaydi.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Bu satr ushbu saytda o‘rnatilgan tarjimalar orasida yo‘q. Qayta qidiring va uni ro‘yxatdan tanlang.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Bu tarjima siz qidirganingizdan keyin yangilangan. Qayta qidiring va satrni yangi ro‘yxatdan tanlang.','To translate this component, Babilim needs its source.'=>'Ushbu komponentni tarjima qilish uchun Babilim uning manba kodiga muhtoj.','Too many attempts. Try again tomorrow.'=>'Juda ko\'p urinish. Ertaga qayta urinib ko\'ring.','Too many reports today. Try again tomorrow.'=>'Bugun hisobotlar juda ko‘p. Ertaga qayta urinib ko‘ring.','Too many requests.'=>'Juda ko‘p so‘rovlar.','Toolbar'=>'Asboblar paneli','Translating…'=>'Tarjima qilinmoqda…','Translation does not load'=>'Tarjima yuklanmaydi','Translation failed'=>'Tarjima muvaffaqiyatsiz tugadi','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'%s papkasiga joylagan tarjima fayllaringiz doim Babilim fayllaridan ustun turadi. Ular siz belgini olib tashlamaguningizcha saqlanadi.','Translation requested.'=>'Tarjima so\'raldi.','Translations'=>'Tarjimalar','Type'=>'Turi','Type at least 2 characters to search.'=>'Qidirish uchun kamida 2 ta belgi kiriting.','Unexpected HTTP %d response.'=>'Kutilmagan HTTP %d javobi.','Uninstall'=>'O\'chirish','Unknown kind: %s'=>'Noma’lum tur: %s','Unsafe domain: %s'=>'Xavfli domen: %s','Unsafe locale: %s'=>'Xavfli lokal: %s','Unsafe slug: %s'=>'Xavfli slug: %s','Unsafe text_domain: %s'=>'Xavfli text_domain: %s','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Kutilayotgan 20 tagacha diagnostika hodisasi (masalan, yaxlitlikni tekshirishdan o\'tmagan fayl haqidagi hodisa). Har biri faqat kod, komponent va lokaldan iborat bo\'lib, hech qachon satrlar mazmuni yoki tarjima matnini o\'z ichiga olmaydi.','Update'=>'Yangilash','Update available'=>'Yangilanish mavjud','Updates'=>'Yangilanishlar','Updating…'=>'Yangilanmoqda…','Upgrade this site'=>'Ushbu saytni yangilash','Upload and request'=>'Yuklash va so‘rash','Upload cancelled.'=>'Yuklash bekor qilindi.','Upload complete — translation requested.'=>'Yuklash yakunlandi — tarjima so\'raldi.','Upload expired before it finished'=>'Yuklash tugamasdan muddati tugadi','Upload in progress — continue or cancel'=>'Yuklash davom etmoqda — davom ettiring yoki bekor qiling','Upload this component?'=>'Ushbu komponent yuklansinmi?','Upload was not accepted'=>'Yuklash qabul qilinmadi','Uploading'=>'Yuklanmoqda','Uploading part %1$d of %2$d…'=>'%2$d qismdan %1$d-qism yuklanmoqda…','Uploading…'=>'Yuklanmoqda…','Verified'=>'Tasdiqlangan','Verify response was missing site_token.'=>'Tasdiqlash javobida site_token yetishmadi.','Version %s'=>'Versiya %s','What is sent when Babilim checks this site'=>'Babilim bu saytni tekshirganda nima yuboriladi','What is sent when you enable Babilim'=>'Babilim\'ni yoqqaningizda nima yuboriladi','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Babilim ichida biror narsa ishdan chiqqanda, uni GitHub’da ommaviy muammo sifatida e’lon qilish uchun Babilim xizmatiga xatolik hisobotini yuboring. Hisobot ushbu saytdan kelgandek yuboriladi va Babilim xizmatiga yuboriladigan boshqa barcha so‘rovlar bilan bir xil autentifikatsiyadan foydalanadi. Xizmat GitHub’da ommaviy muammo sifatida faqat xatolik kodi va versiyalarni e’lon qiladi; ommaviy muammoda sayt manzili, kontent yoki fayl yo‘llari bo‘lmaydi. Sukut bo‘yicha o‘chirilgan.','Where you saw this (optional)'=>'Buni qayerda ko\'rdingiz (ixtiyoriy)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Bu yoqilgan bo‘lsa, xizmat siz boshqarayotgan tillar uchun mavjud deb ko‘rsatgan tarjimalar kuniga ikki marta sinxronlash vaqtida o‘rnatiladi.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Bu kontekst uchun noto\'g\'ri','Wrong meaning'=>'Noto\'g\'ri ma\'no','Wrong plural form'=>'Noto\'g\'ri ko\'plik shakli','Wrong term'=>'Noto\'g\'ri atama','Yes'=>'Ha','You are not allowed to do this.'=>'Sizga bu amalni bajarishga ruxsat berilmagan.','Your PHP version, for compatibility.'=>'PHP versiyangiz, moslik uchun.','Your WordPress version, to serve compatible translation files.'=>'Mos tarjima fayllarini yetkazib berish uchun WordPress versiyangiz.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Yangi tiklash kodingiz: %s. Uni xavfsiz joyda saqlang — avvalgi kod endi ishlamaydi.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Hisobotingiz AI modellari tomonidan avtomatik qayta ishlanadi va boshqa saytlar uchun ushbu tarjimani yaxshilashi mumkin.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Saytingiz javob berdi, lekin kutilgan javob bilan emas. REST API boshqa plagin tomonidan o\'zgartirilgan bo\'lishi yoki bu endpoint keshlangan bo\'lishi mumkin; iltimos, /wp-json/babilim/v1/challenge manzilini keshlash va qayta yozishdan chiqarib qo\'ying.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Saytingizning javob berishi juda uzoq vaqt oldi. Iltimos, keyinroq qayta urinib ko\'ring va hostingingiz juda sekin yoki haddan tashqari band emasligini tekshiring.','Zip has no manifest.json.'=>'Zip ichida manifest.json yo\'q.','Zip is missing expected default file: %s'=>'Zip arxivda kutilgan standart fayl yo‘q: %s','Zip is missing expected file: %s'=>'Zip arxivda kutilgan fayl yo‘q: %s','_manifest.json has an unexpected structure'=>'_manifest.json kutilmagan tuzilishga ega','could not read _manifest.json: %s'=>'_manifest.json faylini o‘qib bo‘lmadi: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest mavjud emas yoki \'%s\' yaroqsiz.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest ichidagi \'server_build_id\' yaroqli build identifikatori emas.','failed to parse _manifest.json: %s'=>'_manifest.json faylini tahlil qilib bo‘lmadi: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'u boshqariladigan %2$d ta komponentdan %1$d tasini egasiz qoldiradi (yarmidan ko\'proq)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'u boshqariladigan barcha %1$s komponentlarini egasiz qoldiradi (%2$d tadan %2$d tasi)','l10n.php entry count mismatch for %s'=>'%s uchun l10n.php yozuvlari soni mos kelmadi','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json faylida yaroqsiz \'default_domain_entries\' bor.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json faylida yaroqsiz \'default_domain_files\' bor.','manifest.json in the zip is not valid JSON.'=>'zip ichidagi manifest.json yaroqli JSON emas.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json da \'%s\' yo\'q yoki yaroqsiz.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json mavjud emas yoki \'build_no\' yaroqsiz.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json da \'entries\' yo\'q yoki yaroqsiz.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json mavjud emas yoki \'extra_domains\' yaroqsiz.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json da \'files\' yo\'q yoki yaroqsiz.','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json dagi \'%s\' kutilgan qiymatga mos kelmaydi.','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json faylidagi \'contract\' yaroqli versiya qatori emas.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json faylidagi \'kind\' qiymati \'plugin\' yoki \'theme\' bo\'lishi kerak.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json faylidagi \'server_build_id\' yaroqli build identifikatori emas.','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json faylidagi \'status\' qiymati \'published\' bo\'lishi kerak.','nonce must be a hexadecimal string.'=>'nonce o\'n oltilik satr bo\'lishi kerak.','per day'=>'kuniga','rc_…'=>'rc_…','sha256 mismatch for %s'=>'%s uchun sha256 mos kelmadi','sha256 mismatch for default/%s'=>'default/%s uchun sha256 mos kelmadi','component kind in the sweep brake messageplugin'=>'plagin','component kind in the sweep brake messagetheme'=>'mavzu','problem report categoryOther'=>'Boshqa','translation statusAvailable'=>'Mavjud','translation statusInstalled'=>'O\'rnatilgan']];